// Wektory kodów QR z web/qr.js (node): renderer natywny musi dać te same moduły.

#[test]
fn qr_matches_qr_js() {
    let cases: [(&str, &str); 3] = [
        ("https://info24.example/wesprzyj", ""),
        ("ŻÓŁĆ 123", ""),
        ("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", ""),
    ];
    for (text, want) in cases {
        let m = vizrs_render::qr::matrix(text).expect("fits");
        let got: Vec<String> = m.iter().map(|r| r.iter().map(|&b| if b { '1' } else { '0' }).collect()).collect();
        assert_eq!(got.join("/"), want, "{text}");
    }
}
